/**
 * Tests for recursive agent delegation in backend/handlers/chat.ts.
 *
 * The file is written to run under `deno test backend/handlers/chat.test.ts`.
 * It is also safe to load under vitest (the test runner is a no-op outside
 * Deno) so the existing `npm test` suite is not disturbed.
 */
import {
  DELEGATE_TASK_TOOL,
  DELEGATION_NO_OUTPUT_PLACEHOLDER,
  extractDelegateTaskToolUses,
  buildToolResultContentBlock,
  runSubAgentForDelegation,
  processDelegateTaskToolUses,
  type DelegationContext,
} from "./chat.ts";
import { globalRegistry } from "../providers/registry.ts";

// ---------------------------------------------------------------------------
// Minimal assertion helpers (kept dependency-free so the file runs under Deno)
// ---------------------------------------------------------------------------

export function assert(condition: unknown, message?: string): asserts condition {
  if (!condition) {
    throw new Error(message ?? "Assertion failed");
  }
}

export function assertEquals<T>(actual: T, expected: T, message?: string): void {
  if (actual !== expected) {
    throw new Error(
      message ??
        `Expected ${JSON.stringify(expected)} but got ${JSON.stringify(actual)}`,
    );
  }
}

// Use Deno.test when running under Deno, otherwise a harmless no-op so vitest
// can load the module without reporting a failing test file.
const denoGlobal = (globalThis as { Deno?: { test: unknown } }).Deno;
const test = denoGlobal?.test
  ? (name: string, fn: () => void | Promise<void>) => {
      (denoGlobal.test as (n: string, f: () => void | Promise<void>) => void)(
        name,
        fn,
      );
    }
  : (_name: string, _fn: () => void | Promise<void>) => {};

// ---------------------------------------------------------------------------
// Test helpers
// ---------------------------------------------------------------------------

function makeProvider(
  responses: Array<Record<string, unknown>>,
): {
  id: string;
  name: string;
  type: "openai";
  supportsImages: () => boolean;
  executeChat: () => AsyncGenerator<Record<string, unknown>>;
} {
  return {
    id: "test-provider",
    name: "Test Provider",
    type: "openai",
    supportsImages: () => true,
    async *executeChat() {
      for (const response of responses) {
        yield response;
      }
    },
  };
}

/** Replace registry lookups with the provided maps. */
function stubRegistry(
  agents: Record<string, unknown>,
  providers: Record<string, ReturnType<typeof makeProvider>>,
): void {
  globalRegistry.getAgent = (id: string) => agents[id] as never;
  globalRegistry.getProviderForAgent = (id: string) =>
    providers[id] as never;
}

function makeContext(overrides: Partial<DelegationContext> = {}): DelegationContext {
  return {
    requestId: "req-1",
    sessionId: "session-1",
    requestAbortControllers: new Map<string, AbortController>(),
    ...overrides,
  };
}

async function collect<T>(generator: AsyncGenerator<T>): Promise<T[]> {
  const items: T[] = [];
  for await (const item of generator) {
    items.push(item);
  }
  return items;
}

function firstToolResult(response: unknown): {
  type: string;
  tool_use_id: string;
  content: string;
  is_error: boolean;
} {
  const data = (response as {
    data?: { message?: { content?: unknown } };
  }).data;
  const content = data?.message?.content;
  assert(Array.isArray(content) && content.length === 1, "expected one tool_result");
  const block = content[0] as {
    type: string;
    tool_use_id: string;
    content: string;
    is_error: boolean;
  };
  return block;
}

function delegateContent(
  agentId: string,
  instructions: string,
  toolUseId = "toolu_1",
): Array<Record<string, unknown>> {
  return [
    {
      type: "tool_use",
      id: toolUseId,
      name: DELEGATE_TASK_TOOL,
      input: { agent_id: agentId, instructions },
    },
  ];
}

