test("extracts delegate_task tool use with object input", () => {
  const content = [
    { type: "text", text: "thinking" },
    {
      type: "tool_use",
      id: "toolu_abc",
      name: DELEGATE_TASK_TOOL,
      input: { agent_id: "worker", instructions: "implement X" },
    },
  ];

  const tasks = extractDelegateTaskToolUses(content);
  assertEquals(tasks.length, 1);
  assertEquals(tasks[0].toolUseId, "toolu_abc");
  assertEquals(tasks[0].agentId, "worker");
  assertEquals(tasks[0].instructions, "implement X");
});

test("extracts delegate_task tool use with JSON-string input", () => {
  const content = [
    {
      type: "tool_use",
      id: "toolu_json",
      name: DELEGATE_TASK_TOOL,
      input: JSON.stringify({ agent_id: "ux", instructions: "review design" }),
    },
  ];

  const tasks = extractDelegateTaskToolUses(content);
  assertEquals(tasks.length, 1);
  assertEquals(tasks[0].toolUseId, "toolu_json");
  assertEquals(tasks[0].agentId, "ux");
  assertEquals(tasks[0].instructions, "review design");
});

test("ignores non delegate_task tool uses", () => {
  const content = [
    { type: "tool_use", id: "toolu_bash", name: "Bash", input: { command: "ls" } },
    { type: "text", text: "plain" },
  ];
  const tasks = extractDelegateTaskToolUses(content);
  assertEquals(tasks.length, 0);
});

