test("builds tool_result block with matching tool_use_id", () => {
  const block = buildToolResultContentBlock("toolu_1", "the output", false);
  assertEquals(block.type, "tool_result");
  assertEquals(block.tool_use_id, "toolu_1");
  assertEquals(block.content, "the output");
  assertEquals(block.is_error, false);
});

