test("returns unknown agent when no agent or provider is registered", async () => {
  stubRegistry({}, {});
  const result = await runSubAgentForDelegation(
    makeContext(),
    "ghost-agent",
    "do the thing",
  );

  assertEquals(result.agentKnown, false);
  assertEquals(result.isError, true);
  assert(
    result.content.includes("ghost-agent"),
    `content should include requested agent_id, got: ${result.content}`,
  );
});

test("runs sub-agent on instructions and accumulates text output", async () => {
  stubRegistry(
    {
      worker: { id: "worker", name: "Worker", description: "", provider: "test", config: {} },
    },
    {
      worker: makeProvider([
