test("uses placeholder when sub-agent produces no text", async () => {
  stubRegistry(
    {
      worker: { id: "worker", name: "Worker", description: "", provider: "test", config: {} },
    },
    { worker: makeProvider([]) },
  );

  const result = await runSubAgentForDelegation(
    makeContext(),
    "worker",
    "silent task",
  );

  assertEquals(result.agentKnown, true);
  assertEquals(result.isError, false);
  assertEquals(result.content, DELEGATION_NO_OUTPUT_PLACEHOLDER);
