test("reports sub-agent failure as is_error without agentKnown=false", async () => {
  stubRegistry(
    {
      worker: { id: "worker", name: "Worker", description: "", provider: "test", config: {} },
    },
    {
      worker: makeProvider([
        { type: "text", content: "partial output" },
        { type: "error", error: "sub-agent blew up" },
      ]),
    },
  );

  const result = await runSubAgentForDelegation(
    makeContext(),
    "worker",
    "fragile task",
