// processDelegateTaskToolUses
// ---------------------------------------------------------------------------

test("feeds back a single tool_result with matching tool_use_id", async () => {
  stubRegistry(
    {
      worker: { id: "worker", name: "Worker", description: "", provider: "test", config: {} },
    },
    { worker: makeProvider([{ type: "text", content: "orchestrator output" }]) },
  );

  const context = makeContext({ delegationPath: ["orchestrator"] });
  const responses = await collect(
    processDelegateTaskToolUses(delegateContent("worker", "go"), context),
  );

  const errors = responses.filter((r) => r.type === "error");
  assertEquals(errors.length, 0, "no stream-level error expected on success");

  const toolResults = responses.filter((r) => r.type === "claude_json");
  assertEquals(toolResults.length, 1);

  const block = firstToolResult(toolResults[0]);
  assertEquals(block.type, "tool_result");
  assertEquals(block.tool_use_id, "toolu_1");
  assertEquals(block.is_error, false);
  assertEquals(block.content, "orchestrator output");
});

test("unknown agent emits stream error and is_error tool_result with agent_id", async () => {
  stubRegistry({}, {});

  const context = makeContext({ delegationPath: ["orchestrator"] });
  const responses = await collect(
    processDelegateTaskToolUses(delegateContent("missing-agent", "go"), context),
  );

  const errors = responses.filter((r) => r.type === "error");
  assertEquals(errors.length, 1);
  assert(
    (errors[0] as { error?: string }).error!.includes("missing-agent"),
    "stream error should mention requested agent_id",
  );

  const toolResults = responses.filter((r) => r.type === "claude_json");
  assertEquals(toolResults.length, 1);
  const block = firstToolResult(toolResults[0]);
  assertEquals(block.is_error, true);
  assert(
    block.content.includes("missing-agent"),
    `tool_result content should include requested agent_id, got: ${block.content}`,
  );
});

test("sub-agent error emits only is_error tool_result, no stream error", async () => {
  stubRegistry(
    {
      worker: { id: "worker", name: "Worker", description: "", provider: "test", config: {} },
    },
    {
      worker: makeProvider([{ type: "error", error: "internal failure" }]),
    },
  );

  const context = makeContext({ delegationPath: ["orchestrator"] });
  const responses = await collect(
    processDelegateTaskToolUses(delegateContent("worker", "go"), context),
  );

  const errors = responses.filter((r) => r.type === "error");
  assertEquals(errors.length, 0, "no stream-level error for sub-agent failure");

  const toolResults = responses.filter((r) => r.type === "claude_json");
  assertEquals(toolResults.length, 1);
  const block = firstToolResult(toolResults[0]);
  assertEquals(block.is_error, true);
  assert(block.content.includes("internal failure"), block.content);
});

test("circular delegation emits stream error mentioning circular", async () => {
  stubRegistry(
    {
      worker: { id: "worker", name: "Worker", description: "", provider: "test", config: {} },
    },
    { worker: makeProvider([{ type: "text", content: "output" }]) },
  );

  const context = makeContext({
    delegationPath: ["orchestrator", "worker"],
  });
  const responses = await collect(
    processDelegateTaskToolUses(delegateContent("worker", "come back"), context),
  );

  const errors = responses.filter((r) => r.type === "error");
  assertEquals(errors.length, 1);
  assert(
    (errors[0] as { error?: string }).error!.toLowerCase().includes("circular"),
    "stream error should mention circular delegation",
  );

  // No tool_result feed-back for circular delegation.
  const toolResults = responses.filter((r) => r.type === "claude_json");
  assertEquals(toolResults.length, 0);
});

test("delegation result is fed back as a user message with tool_result", async () => {
  stubRegistry(
    {
      worker: { id: "worker", name: "Worker", description: "", provider: "test", config: {} },
    },
    { worker: makeProvider([{ type: "text", content: "ready" }]) },
  );

  const context = makeContext({ delegationPath: ["orchestrator"] });
  const responses = await collect(
    processDelegateTaskToolUses(delegateContent("worker", "prepare"), context),
  );

  const claudeJson = responses.find((r) => r.type === "claude_json");
  assert(claudeJson, "expected a claude_json message");

  const data = claudeJson.data as {
    type: string;
    message: { role: string; content: unknown };
    parent_tool_use_id: unknown;
    session_id: string;
  };
  assertEquals(data.type, "user");
  assertEquals(data.message.role, "user");
  const content = data.message.content as Array<Record<string, unknown>>;
  assertEquals(content.length, 1);
  // The feed-back is a JSON-serializable object with type/is_error/content/tool_use_id.
  assertEquals(JSON.parse(JSON.stringify(content[0])).tool_use_id, "toolu_1");
});
