import { describe, it, expect, beforeEach } from "vitest";
import {
  DELEGATE_TASK_TOOL,
  DELEGATION_NO_OUTPUT_PLACEHOLDER,
  extractDelegateTaskToolUses,
  buildToolResultContentBlock,
  runSubAgentForDelegation,
  processDelegateTaskToolUses,
  type DelegationContext,
} from "../../handlers/chat.ts";
import { globalRegistry } from "../../providers/registry.ts";

type StubProvider = {
  type: string;
  executeChat: () => AsyncGenerator<any>;
};

function makeProvider(responses: any[]): any {
  return {
    id: "test-provider",
    name: "Test Provider",
    type: "openai",
    supportsImages: () => true,
    async *executeChat() {
      for (const r of responses) yield r;
    },
  };
}

function stubRegistry(agents: Record<string, unknown>, providers: Record<string, any>) {
  globalRegistry.getAgent = ((id: string) => agents[id]) as any;
  globalRegistry.getProviderForAgent = ((id: string) => providers[id]) as any;
}

function makeContext(overrides: Partial<DelegationContext> = {}): DelegationContext {
  return { requestId: "req-1", sessionId: "s1", requestAbortControllers: new Map(), ...overrides };
}

async function collect<T>(g: AsyncGenerator<T>): Promise<T[]> {
  const out: T[] = [];
  for await (const x of g) out.push(x);
  return out;
}

describe("delegation helpers (chat.ts)", () => {
  it("extracts delegate_task", () => {
    const tasks = extractDelegateTaskToolUses([
      { type: "tool_use", id: "t1", name: DELEGATE_TASK_TOOL, input: { agent_id: "w", instructions: "go" } },
    ]);
    expect(tasks).toEqual([{ toolUseId: "t1", agentId: "w", instructions: "go" }]);
  });

  it("builds tool_result block", () => {
    const block = buildToolResultContentBlock("t1", "out", false);
    expect(block).toEqual({ type: "tool_result", tool_use_id: "t1", content: "out", is_error: false });
  });

  it("unknown agent", async () => {
    stubRegistry({}, {});
    const result = await runSubAgentForDelegation(makeContext(), "ghost", "do");
    expect(result.agentKnown).toBe(false);
    expect(result.content).toContain("ghost");
  });

  it("collects text output", async () => {
    stubRegistry({ w: {} }, { w: makeProvider([{ type: "text", content: "line1" }, { type: "text", content: "line2" }]) });
    const result = await runSubAgentForDelegation(makeContext(), "w", "go");
    expect(result.isError).toBe(false);
    expect(result.content).toContain("line1");
    expect(result.content).toContain("line2");
  });

  it("placeholder on no output", async () => {
    stubRegistry({ w: {} }, { w: makeProvider([]) });
    const result = await runSubAgentForDelegation(makeContext(), "w", "go");
    expect(result.content).toBe(DELEGATION_NO_OUTPUT_PLACEHOLDER);
  });

  it("sub-agent error", async () => {
    stubRegistry({ w: {} }, { w: makeProvider([{ type: "error", error: "boom" }]) });
    const result = await runSubAgentForDelegation(makeContext(), "w", "go");
    expect(result.isError).toBe(true);
    expect(result.content).toContain("boom");
  });

  it("process success -> tool_result matching id", async () => {
    stubRegistry({ w: {} }, { w: makeProvider([{ type: "text", content: "done" }]) });
    const content = [{ type: "tool_use", id: "tu1", name: DELEGATE_TASK_TOOL, input: { agent_id: "w", instructions: "go" } }];
    const responses = await collect(processDelegateTaskToolUses(content, makeContext({ delegationPath: ["o"] })));
    expect(responses.filter(r => r.type === "error").length).toBe(0);
    const tr = responses.find(r => r.type === "claude_json");
    const block = (tr as any).data.message.content[0];
    expect(block.tool_use_id).toBe("tu1");
    expect(block.is_error).toBe(false);
    expect(block.content).toBe("done");
  });

  it("process unknown -> stream error + is_error tool_result with agent_id", async () => {
    stubRegistry({}, {});
    const content = [{ type: "tool_use", id: "tu2", name: DELEGATE_TASK_TOOL, input: { agent_id: "missing", instructions: "go" } }];
    const responses = await collect(processDelegateTaskToolUses(content, makeContext({ delegationPath: ["o"] })));
    const errors = responses.filter(r => r.type === "error");
    expect(errors.length).toBe(1);
    expect((errors[0] as any).error).toContain("missing");
    const tr = responses.find(r => r.type === "claude_json");
    const block = (tr as any).data.message.content[0];
    expect(block.is_error).toBe(true);
    expect(block.content).toContain("missing");
  });

  it("process sub-agent error -> only tool_result is_error, no stream error", async () => {
    stubRegistry({ w: {} }, { w: makeProvider([{ type: "error", error: "failed" }]) });
    const content = [{ type: "tool_use", id: "tu3", name: DELEGATE_TASK_TOOL, input: { agent_id: "w", instructions: "go" } }];
    const responses = await collect(processDelegateTaskToolUses(content, makeContext({ delegationPath: ["o"] })));
    expect(responses.filter(r => r.type === "error").length).toBe(0);
    const tr = responses.find(r => r.type === "claude_json");
    const block = (tr as any).data.message.content[0];
    expect(block.is_error).toBe(true);
  });

  it("process circular -> stream error mentioning circular", async () => {
    stubRegistry({ w: {} }, { w: makeProvider([{ type: "text", content: "out" }]) });
    const content = [{ type: "tool_use", id: "tu4", name: DELEGATE_TASK_TOOL, input: { agent_id: "w", instructions: "back" } }];
    const responses = await collect(processDelegateTaskToolUses(content, makeContext({ delegationPath: ["o", "w"] })));
    const errors = responses.filter(r => r.type === "error");
    expect(errors.length).toBe(1);
    expect((errors[0] as any).error.toLowerCase()).toContain("circular");
  });
});
