        with mock.patch("bandit.cli.main.b_cache.Cache") as mock_cache:
            mock_cache.return_value.list_files.return_value = ["a.py", "b.py"]
            with mock.patch("builtins.print") as mock_print:
                self.assertRaisesRegex(SystemExit, "0", bandit.main)
                printed = [call[0][0] for call in mock_print.call_args_list]
                self.assertIn("a.py", printed)
                self.assertIn("b.py", printed)

