import { createContainer } from '../container'
import { asFunction } from '../resolvers'
import { AwilixInitializationError } from '../errors'

describe('initialization edge cases', () => {
  it('allows in-flight initializers in a level to complete before rollback', async () => {
    const events: string[] = []
    const container = createContainer()
    container.register({
      slow: asFunction(() => ({}))
        .singleton()
        .initializer(async () => {
          events.push('slow-start')
          await new Promise((r) => setTimeout(r, 50))
          events.push('slow-end')
          return {}
        }),
      failer: asFunction(() => ({}))
        .singleton()
        .initializer(async () => {
          events.push('failer')
          throw new Error('nope')
        }),
    })
    let err: any
    try {
      await container.initialize()
    } catch (e) {
      err = e
    }
    expect(err).toBeInstanceOf(AwilixInitializationError)
    expect(events).toContain('slow-end')
    expect(events.indexOf('slow-end')).toBeGreaterThan(
      events.indexOf('slow-start'),
    )
  })

  it('rolls back all initialized services across levels in reverse order', async () => {
    const order: string[] = []
    const container = createContainer()
    container.register({
      a: asFunction(() => ({ name: 'a' }))
        .singleton()
        .disposer(() => {
          order.push('dispose-a')
        })
        .initializer(async () => {
          order.push('init-a')
          return { name: 'a' }
        }),
      b: asFunction(({ a }: any) => ({ a }))
        .singleton()
        .disposer(() => {
          order.push('dispose-b')
        })
        .initializer(async () => {
          order.push('init-b')
          throw new Error('b-fail')
        }),
    })
    try {
      await container.initialize()
    } catch (e) {
      // expected
    }
    // a is level 0, b is level 1. b fails, a should be disposed.
    expect(order).toEqual(['init-a', 'init-b', 'dispose-a'])
  })

  it('does not let disposer errors override the original initialization error', async () => {
    const container = createContainer()
    container.register({
      a: asFunction(() => ({ name: 'a' }))
        .singleton()
        .disposer(() => {
          throw new Error('dispose-boom')
        })
        .initializer(async () => {
          return { name: 'a' }
        }),
      b: asFunction(() => ({ name: 'b' }))
        .singleton()
        .initializer(async () => {
          throw new Error('init-boom')
        }),
    })
    let err: any
    try {
      await container.initialize()
    } catch (e) {
      err = e
    }
    expect(err).toBeInstanceOf(AwilixInitializationError)
    expect(String(err.message)).toContain('init-boom')
    expect(err.cause.message).toBe('init-boom')
  })

  it('supports initializer returning a replacement', async () => {
    const container = createContainer()
    container.register({
      svc: asFunction<any>(() => ({ original: true }))
        .singleton()
        .initializer(async () => ({ replaced: true })),
    })
    await container.initialize()
    expect(container.resolve('svc')).toEqual({ replaced: true })
  })

  it('scoped container initializes independently without reinitializing parent singletons', async () => {
    let singletonInits = 0
    let scopedInits = 0
    const container = createContainer()
    container.register({
      singletonSvc: asFunction(() => ({}))
        .singleton()
        .initializer(async () => {
          singletonInits++
          return {}
        }),
    })
    await container.initialize()
    expect(singletonInits).toBe(1)

    const scope = container.createScope().register({
      scopedSvc: asFunction(() => ({}))
        .scoped()
        .initializer(async () => {
          scopedInits++
          return {}
        }),
    })
    await scope.initialize()
    expect(scopedInits).toBe(1)
    expect(singletonInits).toBe(1) // parent singleton not reinitialized
    expect(scope.resolve('scopedSvc')).toBeDefined()
  })

  it('services without initializers can be resolved before initialize()', async () => {
    const container = createContainer()
    container.register({
      plain: asFunction(() => ({ ok: true })).singleton(),
    })
    expect(container.resolve('plain')).toEqual({ ok: true })
  })

  it('concurrency 0 is treated as unlimited', async () => {
    const container = createContainer()
    for (let i = 0; i < 3; i++) {
      container.register({
        [`s${i}`]: asFunction(() => ({}))
          .singleton()
          .initializer(async () => {}),
      })
    }
    const result = await container.initialize({ concurrency: 0 as any })
    expect(result.metrics.s0.level).toBe(0)
  })

  it('dispose resets initialization state allowing re-initialize', async () => {
    let calls = 0
    const container = createContainer()
    container.register({
      svc: asFunction(() => ({}))
        .singleton()
        .initializer(async () => {
          calls++
          return {}
        }),
    })
    await container.initialize()
    await container.dispose()
    await container.initialize()
    expect(calls).toBe(2)
  })
})
