import { describe, it, expect, vi, beforeEach } from "vitest";
import { Context } from "hono";
import { handleMultiAgentChatRequest } from "../../handlers/multiAgentChat.ts";
import { globalRegistry } from "../../providers/registry.ts";
import { globalImageHandler } from "../../utils/imageHandling.ts";
import type { ChatRequest } from "../../../shared/types.ts";

// Mock the registry and image handler
vi.mock("../../providers/registry.ts", () => ({
  globalRegistry: {
    getProviderForAgent: vi.fn(),
    getAgent: vi.fn(),
  },
}));

vi.mock("../../utils/imageHandling.ts", () => ({
  globalImageHandler: {
    captureScreenshot: vi.fn(),
  },
}));

type ProviderInput = { message: string; requestId: string; sessionId?: string };

/** Build a provider whose executeChat dispatches on the incoming message. */
function scriptedProvider(
  scripts: Array<{
    match?: (input: ProviderInput) => boolean;
    responses: Array<Record<string, unknown>>;
  }>,
) {
  return {
    id: "mock-provider",
    name: "Mock Provider",
    type: "openai" as const,
    supportsImages: () => true,
    executeChat: vi.fn(async function* (input: ProviderInput) {
      for (const script of scripts) {
        if (!script.match || script.match(input)) {
          for (const response of script.responses) {
            yield response;
          }
          return;
        }
      }
      yield { type: "error", error: "No script matched" };
    }),
  };
}

function makeAgent(id: string, providerId = "mock-provider") {
  return {
    id,
    name: id,
    description: `Agent ${id}`,
    provider: providerId,
    config: { temperature: 0.7, maxTokens: 1000 },
  };
}

async function collectResponse(c: Partial<Context>, requestAbortControllers: Map<string, AbortController>) {
  const response = await handleMultiAgentChatRequest(
    c as Context,
    requestAbortControllers,
  );
  const reader = response.body!.getReader();
  const decoder = new TextDecoder();
  let streamData = "";
  while (true) {
    const { done, value } = await reader.read();
    if (done) break;
    streamData += decoder.decode(value);
  }
  return streamData
    .split("\n")
    .filter((line) => line.trim())
    .map((line) => JSON.parse(line));
}

describe("recursive agent delegation (delegate_task)", () => {
  let mockContext: Partial<Context>;
  let requestAbortControllers: Map<string, AbortController>;

  beforeEach(() => {
    vi.clearAllMocks();
    requestAbortControllers = new Map();
    mockContext = {
      req: { json: vi.fn() } as any,
      var: { config: { debugMode: true } } as any,
    };
    vi.mocked(globalImageHandler.captureScreenshot).mockResolvedValue({
      success: false,
      error: "Not implemented",
    });
  });

  it("runs the sub-agent on delegated instructions and feeds the single tool_result back so the delegating agent can continue", async () => {
    const delegatorProvider = scriptedProvider([
      {
        match: (i) => !i.message.includes("tool_result"),
        responses: [
          {
            type: "tool_use",
            toolName: "delegate_task",
            toolInput: { agent_id: "writer", instructions: "write the report" },
          },
          { type: "done" },
        ],
      },
      {
        match: (i) => i.message.includes("tool_result"),
        responses: [
          { type: "text", content: "DELEGATE-OK" },
          { type: "done" },
        ],
      },
    ]);
    const writerProvider = scriptedProvider([
      {
        responses: [
          { type: "text", content: "WRITER-OUTPUT" },
          { type: "done" },
        ],
      },
    ]);

    vi.mocked(globalRegistry.getAgent).mockImplementation((id: string) => {
      if (id === "delegator") return makeAgent("delegator");
      if (id === "writer") return makeAgent("writer");
      return null;
    });
    vi.mocked(globalRegistry.getProviderForAgent).mockImplementation((id: string) => {
      if (id === "delegator") return delegatorProvider;
      if (id === "writer") return writerProvider;
      return null;
    });

    vi.mocked(mockContext.req!.json).mockResolvedValue({
      message: "@delegator delegate the report",
      requestId: "req-delegate",
      sessionId: "session-delegate",
    } as ChatRequest);

    const responses = await collectResponse(mockContext, requestAbortControllers);

    const toolUseEvents = responses.filter(
      (r) =>
        r.type === "claude_json" &&
        r.data?.type === "assistant" &&
        Array.isArray(r.data?.message?.content) &&
        r.data.message.content.some((b: any) => b.type === "tool_use" && b.name === "delegate_task"),
    );
    expect(toolUseEvents.length).toBeGreaterThan(0);

    // The streamed tool_use must expose an id.
    const toolUseBlock = (toolUseEvents[0].data.message.content as any[]).find(
      (b) => b.type === "tool_use",
    );
    expect(toolUseBlock.id).toBeTruthy();

    // A tool_result event must be streamed with matching tool_use_id.
    const toolResultEvents = responses.filter(
      (r) => r.type === "claude_json" && r.data?.type === "user",
    );
