    const allText = responses
      .filter((r) => r.type === "claude_json" && r.data?.type === "assistant" && typeof r.data?.content === "string")
      .map((r) => r.data.content);
    expect(allText.some((t) => t.includes("DELEGATE-OK"))).toBe(true);

    // The delegating provider was invoked twice (initial + feed-back re-invocation).
    expect(delegatorProvider.executeChat).toHaveBeenCalledTimes(2);
    // The writer provider was invoked once with the delegated instructions.
    expect(writerProvider.executeChat).toHaveBeenCalledWith(
      expect.objectContaining({
        message: "write the report",
        requestId: "req-delegate",
      }),
      expect.anything(),
    );
  });

  it("uses a placeholder when the sub-agent produces no text and does not error", async () => {
    const delegatorProvider = scriptedProvider([
      {
