    const delegatorProvider = scriptedProvider([
      {
        match: (i) => !i.message.includes("tool_result"),
        responses: [
          {
            type: "tool_use",
            toolName: "delegate_task",
            toolInput: { agent_id: "failing-agent", instructions: "crash now" },
          },
          { type: "done" },
        ],
      },
      {
        match: (i) => i.message.includes("tool_result"),
        responses: [{ type: "done" }],
      },
    ]);
    const failingProvider = scriptedProvider([
      { responses: [{ type: "error", error: "Sub-agent blew up" }] },
    ]);

    vi.mocked(globalRegistry.getAgent).mockImplementation((id: string) =>
      id === "delegator" ? makeAgent("delegator") : makeAgent(id));
    vi.mocked(globalRegistry.getProviderForAgent).mockImplementation((id: string) =>
      id === "delegator" ? delegatorProvider : failingProvider);

    vi.mocked(mockContext.req!.json).mockResolvedValue({
      message: "@delegator call failing-agent",
      requestId: "req-fail",
      sessionId: "session-fail",
    } as ChatRequest);

    const responses = await collectResponse(mockContext, requestAbortControllers);

    // No stream-level error for the sub-agent run failure.
    const streamErrors = responses.filter((r) => r.type === "error");
    expect(streamErrors.length).toBe(0);

    const toolResultEvents = responses.filter(
      (r) => r.type === "claude_json" && r.data?.type === "user",
    );
    expect(toolResultEvents.length).toBeGreaterThan(0);
    const feedBack = JSON.parse((toolResultEvents[0].data.message as any).content);
    expect(feedBack.is_error).toBe(true);
    expect(feedBack.content).toContain("Sub-agent blew up");
  });

  it("supports nested recursive delegation (A -> B -> C)", async () => {
    const aProvider = scriptedProvider([
      {
        match: (i) => !i.message.includes("tool_result"),
        responses: [
          {
            type: "tool_use",
            toolName: "delegate_task",
            toolInput: { agent_id: "b-agent", instructions: "delegate to c-agent" },
          },
          { type: "done" },
        ],
      },
      {
        match: (i) => i.message.includes("tool_result"),
        responses: [{ type: "text", content: "A-DONE" }, { type: "done" }],
      },
    ]);
    const bProvider = scriptedProvider([
      {
        match: (i) => !i.message.includes("tool_result"),
        responses: [
          {
            type: "tool_use",
            toolName: "delegate_task",
            toolInput: { agent_id: "c-agent", instructions: "do the work" },
          },
          { type: "done" },
        ],
      },
      {
        match: (i) => i.message.includes("tool_result"),
        responses: [{ type: "text", content: "B-DONE" }, { type: "done" }],
      },
    ]);
    const cProvider = scriptedProvider([
      { responses: [{ type: "text", content: "C-OUTPUT" }, { type: "done" }] },
    ]);

    vi.mocked(globalRegistry.getAgent).mockImplementation((id: string) => makeAgent(id));
    vi.mocked(globalRegistry.getProviderForAgent).mockImplementation((id: string) =>
      id === "a-agent" ? aProvider : id === "b-agent" ? bProvider : cProvider);

    vi.mocked(mockContext.req!.json).mockResolvedValue({
      message: "@a-agent kick off the workflow",
      requestId: "req-nested",
      sessionId: "session-nested",
    } as ChatRequest);

    const responses = await collectResponse(mockContext, requestAbortControllers);

    // Only the root delegation (A -> B) surfaces as a streamed tool_result;
    // the nested (B -> C) result is fed internally to B.
    const toolResultEvents = responses.filter(
      (r) => r.type === "claude_json" && r.data?.type === "user",
    );
    expect(toolResultEvents.length).toBe(1);

    const feedBack = JSON.parse((toolResultEvents[0].data.message as any).content);
    expect(feedBack.is_error).toBe(false);
    expect(feedBack.content).toContain("B-DONE");

    // The inner sub-agent was run on the delegated instructions.
    expect(cProvider.executeChat).toHaveBeenCalledWith(
      expect.objectContaining({ message: "do the work" }),
