    expect(cProvider.executeChat).toHaveBeenCalledTimes(1);
    expect(bProvider.executeChat).toHaveBeenCalledTimes(2);
    expect(aProvider.executeChat).toHaveBeenCalledTimes(2);

    // Root agent produced its final text after continuing.
    const allText = responses
      .filter((r) => r.type === "claude_json" && r.data?.type === "assistant" && typeof r.data?.content === "string")
      .map((r) => r.data.content);
    expect(allText.some((t) => t.includes("A-DONE"))).toBe(true);
  });

  it("emits a stream-level circular error when delegation is circular", async () => {
    const delegatorProvider = scriptedProvider([
      {
        match: (i) => !i.message.includes("tool_result"),
