go test -run 'TestRequire' ./evaluator/ 2>&1 | tail -30

cd /app && cat > lib/__tests/lexer-shorthand.js <<'EOF'
import assert from 'assert';
import { lexer, fork } from 'css-tree';

function expand(property, value) {
    return lexer.expandShorthand(property, value);
}

function compress(property, longhands) {
    return lexer.compressShorthand(property, longhands);
}

// Expanding then compressing should produce an equivalent shorthand value
// that expands back to the same longhands.
function roundtrip(property, value) {
    const longhands = expand(property, value);

    if (longhands === null) {
        return false;
    }

    const compressed = compress(property, longhands);

    if (compressed === null) {
        return false;
    }

    return JSON.stringify(expand(property, compressed)) === JSON.stringify(longhands);
}

describe('lexer shorthand', () => {
    it('expandShorthand and compressShorthand are functions', () => {
        assert.strictEqual(typeof lexer.expandShorthand, 'function');
        assert.strictEqual(typeof lexer.compressShorthand, 'function');
    });

    describe('box-model shorthands', () => {
        it('margin one value sets all four', () => {
            assert.deepStrictEqual(expand('margin', '1px'), {
                'margin-top': '1px',
                'margin-right': '1px',
                'margin-bottom': '1px',
                'margin-left': '1px'
            });
        });

        it('margin two values set first+third and second+fourth', () => {
            assert.deepStrictEqual(expand('margin', '1px 2px'), {
                'margin-top': '1px',
                'margin-right': '2px',
                'margin-bottom': '1px',
                'margin-left': '2px'
            });
        });

        it('margin three values set first, second+fourth, third', () => {
            assert.deepStrictEqual(expand('margin', '1px 2px 3px'), {
                'margin-top': '1px',
                'margin-right': '2px',
                'margin-bottom': '3px',
                'margin-left': '2px'
            });
        });

        it('margin four values set in order', () => {
            assert.deepStrictEqual(expand('margin', '1px 2px 3px 4px'), {
                'margin-top': '1px',
                'margin-right': '2px',
                'margin-bottom': '3px',
                'margin-left': '4px'
            });
        });

        it('padding and inset distribute the same way', () => {
            assert.deepStrictEqual(expand('padding', '1px 2px 3px 4px'), {
                'padding-top': '1px',
                'padding-right': '2px',
                'padding-bottom': '3px',
                'padding-left': '4px'
            });
            assert.deepStrictEqual(expand('inset', '1px 2px 3px 4px'), {
                top: '1px',
                right: '2px',
                bottom: '3px',
                left: '4px'
            });
        });

        it('border-radius distributes clockwise from top-left', () => {
            assert.deepStrictEqual(expand('border-radius', '10px 20px'), {
                'border-top-left-radius': '10px',
                'border-top-right-radius': '20px',
                'border-bottom-right-radius': '10px',
                'border-bottom-left-radius': '20px'
            });
        });

        it('border-radius supports slash separated horizontal/vertical', () => {
