                'border-top-left-radius': '10px 30px',
                'border-top-right-radius': '20px 40px',
                'border-bottom-right-radius': '10px 30px',
                'border-bottom-left-radius': '20px 40px'
            });
        });

        it('compresses box-model values to the fewest that expand back', () => {
            assert.strictEqual(compress('margin', {
                'margin-top': '1px',
                'margin-right': '1px',
                'margin-bottom': '1px',
                'margin-left': '1px'
            }), '1px');
            assert.strictEqual(compress('margin', {
                'margin-top': '1px',
                'margin-right': '2px',
                'margin-bottom': '1px',
                'margin-left': '2px'
            }), '1px 2px');
            assert.strictEqual(compress('margin', {
                'margin-top': '1px',
                'margin-right': '2px',
                'margin-bottom': '3px',
                'margin-left': '2px'
            }), '1px 2px 3px');
            assert.strictEqual(compress('margin', {
                'margin-top': '1px',
                'margin-right': '2px',
                'margin-bottom': '3px',
                'margin-left': '4px'
            }), '1px 2px 3px 4px');
