const Bluebird = require('bluebird');
const log = require('npmlog');

const reporters = require('../reporters');
const isa = require('./isa');
const ReportFile = require('./report-file');

function setupReporter(name, out, config, app) {
  let reporter;

  if (isa(name, String)) {
    let TestReporter = reporters[name];
    if (TestReporter) {
      reporter = new TestReporter(false, out, config, app);
    }
  } else if (isa(name, Function)) {
    // name is a constructor function, ignore new-cap and instantiate
    // eslint-disable-next-line new-cap
    reporter = new name(false, out, config, app);
  } else {
    reporter = name;
  }

  if (!reporter) {
    throw new Error('Test reporter `' + name + '` not found.');
  }

  return reporter;
}


class Reporter {
  constructor(app, stdout, path) {
    this.app = app;
    this.total = 0;
    this.passed = 0;
    this.skipped = 0;
    this.todo = 0;
    this.finished = false;
    this.closed = false;
    this.launcherReporters = {};
    this.launcherReportFiles = {};

    this.reportFileName = path;
    this.hasLauncherTemplate = path ? ReportFile.hasLauncherTemplate(path) : false;

    let config = app.config;

    let xunitIntermediate = path && config.get('xunit_intermediate_output') && config.get('reporter') === 'xunit';

    if (xunitIntermediate) {
      this.reporters = [
        setupReporter('tap', stdout, config, app)
      ];
    } else {
      this.reporters = [setupReporter(config.get('reporter'), stdout, config, app)];
    }

    if (path) {
      if (xunitIntermediate) {
        this.fileReporter = config.get('reporter');
      } else if (config.appMode === 'dev') {
        let devModeFileReporter = config.get('dev_mode_file_reporter');
        if (!devModeFileReporter) {
          log.warn('You configured a `report_file`, you may want to configure the `dev_mode_file_reporter` as well. Using the `tap` logger now.');
          devModeFileReporter = 'tap';
        }
        this.fileReporter = devModeFileReporter;
      } else {
        this.fileReporter = config.get('reporter');
      }

      if (!this.hasLauncherTemplate) {
        this.reportFile = new ReportFile(path);
        this.reporters.push(setupReporter(this.fileReporter, this.reportFile.outputStream, config, app));
      }
    }
  }

  getLauncherReportFile(launcher) {
    if (!this.launcherReportFiles[launcher]) {
      this.launcherReportFiles[launcher] = new ReportFile(this.reportFileName, { launcher });
    }

    return this.launcherReportFiles[launcher];
  }

  getLauncherReporter(launcher) {
    if (!this.launcherReporters[launcher]) {
      let reportFile = this.getLauncherReportFile(launcher);
      let reporter = setupReporter(this.fileReporter, reportFile.outputStream, this.app.config, this.app);

      if (typeof reporter.setLauncherName === 'function') {
        reporter.setLauncherName(launcher);
      }

      this.launcherReporters[launcher] = reporter;
    }

    return this.launcherReporters[launcher];
  }

  testStarted(name, data) {
    this.reporters.forEach(reporter => {
      if (reporter.testStarted) {
        reporter.testStarted(name, data);
      }
    });

    if (this.hasLauncherTemplate && name && name !== 'testem') {
      let reporter = this.getLauncherReporter(name);
      if (reporter.testStarted) {
        reporter.testStarted(name, data);
      }
    }
  }

  close() {
    if (this.closed) {
      return Bluebird.resolve();
    }
    this.closed = true;

    this.finish();

    if (this.hasLauncherTemplate) {
      return Bluebird.all(Object.values(this.launcherReportFiles).map(reportFile => reportFile.close()));
    }

    if (this.reportFile) {
      return this.reportFile.close();
    }
  }

  hasTests() {
    return this.total > 0;
  }

  hasPassed() {
    return this.total <= ((this.passed || 0) + (this.skipped || 0) + (this.todo || 0));
  }

  report(name, result) {
    this.total++;
    if (result.skipped) {
      this.skipped++;
    } else if (result.passed && !result.todo) {
      this.passed++;
    } else if (!result.passed && result.todo) {
      this.todo++;
    }

    this.reporters.forEach(reporter => {
      reporter.report(name, result);
    });

    if (this.hasLauncherTemplate && name && name !== 'testem') {
      this.getLauncherReporter(name).report(name, result);
    }
  }
}

Reporter.with = (app, stdout, path) => Bluebird.try(() => new Reporter(app, stdout, path)).disposer((reporter, promise) => {
  if (promise.isRejected()) {
    let err = promise.reason();

    if (!err.hideFromReporter) {
      reporter.report(null, {
        passed: false,
        name: err.name || 'unknown error',
        error: {
          message: err.message
        }
      });
    }
  }

  return reporter.close();
});

Reporter.prototype.finish = function() {
  if (this.finished) {
    return;
  }
  this.finished = true;

  this.reporters.forEach(reporter => {
    if (reporter.finish) {
      reporter.finish();
    }
  });

  Object.values(this.launcherReporters).forEach(reporter => {
    if (reporter.finish) {
      reporter.finish();
    }
  });
};

function forwardToReporters(fn, routeByLauncher) {
  return function() {
    let args = Array.prototype.slice.call(arguments);

    this.reporters.forEach(reporter => {
      if (reporter[fn]) {
        reporter[fn].apply(reporter, args);
      }
    });

    if (this.hasLauncherTemplate) {
      let names;
      let forwardArgs;
      if (routeByLauncher && args.length > 0) {
        names = [args[0]];
        forwardArgs = args.slice(1);
      } else {
        names = Object.keys(this.launcherReporters);
        forwardArgs = args;
      }

      names.forEach(name => {
        if (name === 'testem') {
          return;
        }
        let reporter = this.launcherReporters[name];
        if (reporter && reporter[fn]) {
          reporter[fn].apply(reporter, forwardArgs);
        }
      });
    }
  };
}

['onStart', 'onEnd'].forEach(fn => {
  Reporter.prototype[fn] = forwardToReporters(fn, true);
});

Reporter.prototype.reportMetadata = forwardToReporters('reportMetadata', false);

module.exports = Reporter;
