				if tc.msg != "" && !strings.Contains(errs[0].Message, tc.msg) {
					t.Fatalf("wanted message containing %q but got %q", tc.msg, errs[0].Message)
				}
			} else {
				if len(errs) > 0 {
					t.Fatalf("unexpected errors for %q: %v", tc.uses, errs)
				}
			}
		})
	}
}

func TestRuleActionPinningPerPathConfig(t *testing.T) {
	cfg := &Config{
		ActionPinning: &ActionPinningConfig{Level: "major-minor"},
		Paths: map[string]PathConfig{
			".github/workflows/test.yaml": {
				ActionPinning: &ActionPinningConfig{Level: "commit-sha"},
			},
		},
	}

	// The per-path configuration overrides the level to commit-sha.
	r := actionPinningRuleForTest(t, ".github/workflows/test.yaml", cfg, "")
	if err := r.VisitStep(newActionPinningStep("actions/checkout@v4.2.2")); err != nil {
		t.Fatal(err)
	}
	errs := r.Errs()
	if len(errs) == 0 {
		t.Fatal("error did not occur: per-path commit-sha should reject semver ref")
	}
	if !strings.Contains(errs[0].Message, "40-character commit SHA") {
		t.Fatalf("unexpected message: %q", errs[0].Message)
	}

	// A non-matching path should use the global major-minor level.
	r2 := actionPinningRuleForTest(t, ".github/workflows/other.yaml", cfg, "")
	if err := r2.VisitStep(newActionPinningStep("actions/checkout@v4.2.2")); err != nil {
		t.Fatal(err)
	}
	if len(r2.Errs()) > 0 {
		t.Fatalf("unexpected errors: %v", r2.Errs())
	}
}

func TestRuleActionPinningPerPathEnablesRule(t *testing.T) {
	cfg := &Config{
		Paths: map[string]PathConfig{
			".github/workflows/test.yaml": {
				ActionPinning: &ActionPinningConfig{},
			},
		},
	}

	// A per-path entry enables the rule even without a global section.
	r := actionPinningRuleForTest(t, ".github/workflows/test.yaml", cfg, "")
	if err := r.VisitStep(newActionPinningStep("actions/checkout@main")); err != nil {
		t.Fatal(err)
	}
	if len(r.Errs()) == 0 {
		t.Fatal("error did not occur: per-path entry should enable the rule")
	}

	// A non-matching path should keep the rule disabled.
	r2 := actionPinningRuleForTest(t, ".github/workflows/other.yaml", cfg, "")
	if err := r2.VisitStep(newActionPinningStep("actions/checkout@main")); err != nil {
		t.Fatal(err)
	}
	if len(r2.Errs()) > 0 {
		t.Fatalf("unexpected errors: %v", r2.Errs())
	}
}

func TestRuleActionPinningMergeAllowDenyByUnion(t *testing.T) {
	cfg := &Config{
		ActionPinning: &ActionPinningConfig{
			AllowedOwners: []string{"octo-org"},
		},
		Paths: map[string]PathConfig{
			".github/workflows/test.yaml": {
				ActionPinning: &ActionPinningConfig{
					DeniedActions: []string{"octo-org/action"},
				},
			},
		},
	}

	// Global allowed-owners exempts octo-org, but per-path denied-actions makes octo-org/action
	// subject to the check.
	r := actionPinningRuleForTest(t, ".github/workflows/test.yaml", cfg, "")
	if err := r.VisitStep(newActionPinningStep("octo-org/action@main")); err != nil {
		t.Fatal(err)
	}
	if len(r.Errs()) == 0 {
		t.Fatal("error did not occur: denied-actions should take precedence over allowed-owners")
	}

	// A different action under the allowed owner is exempt.
	r2 := actionPinningRuleForTest(t, ".github/workflows/test.yaml", cfg, "")
	if err := r2.VisitStep(newActionPinningStep("octo-org/other@main")); err != nil {
		t.Fatal(err)
	}
	if len(r2.Errs()) > 0 {
		t.Fatalf("unexpected errors: %v", r2.Errs())
	}
}

func TestKnownActionPinningVersion(t *testing.T) {
	tests := []struct {
		action string
		want   string
		ok     bool
	}{
		{"actions/checkout", "actions/checkout@v6", true},
		{"github/codeql-action/init", "github/codeql-action/init@v4", true},
		{"unknown-owner/unknown-action", "", false},
	}
	for _, tc := range tests {
		t.Run(tc.action, func(t *testing.T) {
			got, ok := knownActionPinningVersion(tc.action)
			if tc.ok != ok {
				t.Fatalf("wanted ok=%v but got %v", tc.ok, ok)
			}
			if ok && got != tc.want {
				t.Fatalf("wanted %q but got %q", tc.want, got)
			}
		})
	}
}
