import { createContainer } from '../src/container'
import { asClass, asFunction } from '../src/resolvers'
import {
  AwilixInitializationError,
  AwilixNotInitializedError,
  AwilixResolutionError,
} from '../src/errors'

describe('container.initialize', () => {
  it('returns totalDuration and metrics', async () => {
    const container = createContainer()
    container.register({
      database: asClass(
        class DatabasePool {
          async connect() {
            await new Promise((r) => setTimeout(r, 10))
          }
        },
      )
        .singleton()
        .initializer(async (instance) => {
          await instance.connect()
          return instance
        }),
    })
    const result = await container.initialize()
    expect(typeof result.totalDuration).toBe('number')
    expect(result.totalDuration).toBeGreaterThanOrEqual(0)
    expect(result.metrics.database.duration).toBeGreaterThanOrEqual(0)
    expect(result.metrics.database.level).toBe(0)
  })

  it('register accepts object map', async () => {
    const container = createContainer()
    const result = container.register({
      database: asClass(class DatabasePool {})
        .singleton()
        .initializer(() => ({ ready: true })),
    })
    expect(result).toBe(container)
    expect(container.hasRegistration('database')).toBe(true)
    await container.initialize()
    expect(container.resolve('database').ready).toBe(true)
  })

  it('initializer is invoked', async () => {
    const container = createContainer()
    const initializer = jest.fn((instance) => instance)
    container.register({
      service: asFunction(() => ({ ok: true }))
        .singleton()
        .initializer(initializer),
    })
    await container.initialize()
    expect(initializer).toHaveBeenCalledTimes(1)
  })

  it('asClass initializer runs', async () => {
    const container = createContainer()
    let connected = false
    class DatabasePool {
      connected: boolean
      constructor() {
        this.connected = false
      }
      connect() {
        connected = true
      }
    }
    container.register({
      database: asClass(DatabasePool).singleton().initializer(async (instance) => {
        instance.connect()
        return instance
      }),
    })
    await container.initialize()
    expect(connected).toBe(true)
    expect(container.resolve('database')).toBeInstanceOf(DatabasePool)
  })

  it('asFunction and asClass both initialize', async () => {
    const container = createContainer()
    container.register({
      fnService: asFunction(() => ({ kind: 'fn' }))
        .singleton()
        .initializer((i) => i),
      classService: asClass(class ClassService {})
        .singleton()
        .initializer((i) => i),
    })
    const result = await container.initialize()
    expect(result.metrics.fnService.level).toBe(0)
    expect(result.metrics.classService.level).toBe(0)
  })

  it('singleton initializer runs once', async () => {
    const container = createContainer()
    const initializer = jest.fn((instance) => instance)
    container.register({
      service: asClass(class Service {})
        .singleton()
        .initializer(initializer),
    })
    await container.initialize()
    await container.initialize()
    expect(initializer).toHaveBeenCalledTimes(1)
  })

  it('resolve uninitialized throws not initialized', async () => {
    const container = createContainer()
    container.register({
      database: asClass(class DatabasePool {})
        .singleton()
        .initializer((i) => i),
    })
    let caught: any = null
    try {
      container.resolve('database')
    } catch (err) {
      caught = err
    }
    expect(caught).toBeInstanceOf(AwilixNotInitializedError)
    expect(caught.message).toContain('not initialized')
  })

  it('initialization error carries name message and cause', async () => {
    const container = createContainer()
    const boom = new Error('kaboom')
    container.register({
      database: asClass(class DatabasePool {})
        .singleton()
        .initializer(async () => {
          throw boom
        }),
    })
    let caught: any = null
    try {
      await container.initialize()
    } catch (err) {
      caught = err
    }
    expect(caught).toBeInstanceOf(AwilixInitializationError)
    expect(caught.message).toContain('database')
    expect(caught.message).toContain('kaboom')
    expect(caught.cause).toBe(boom)
  })

  it('re-initialize after failure throws', async () => {
    const container = createContainer()
    container.register({
      database: asClass(class DatabasePool {})
        .singleton()
        .initializer(async () => {
          throw new Error('kaboom')
        }),
    })
    try {
      await container.initialize()
    } catch (e) {
      /* expected */
    }
    let caught: any = null
    try {
      await container.initialize()
    } catch (err) {
      caught = err
    }
    expect(caught).toBeDefined()
    expect(caught.message).toMatch(/previously failed|Cannot re-initialize/)
  })

  it('initialize accepts concurrency option', async () => {
    const container = createContainer()
    container.register({
      a: asClass(class A {}).singleton().initializer((i) => i),
      b: asClass(class B {}).singleton().initializer((i) => i),
    })
    const result = await container.initialize({ concurrency: 1 })
    expect(result.metrics.a).toBeDefined()
    expect(result.metrics.b).toBeDefined()
  })

  it('levels follow dependency graph', async () => {
    const container = createContainer()
    class Repository {
      database: any
      constructor(database: any) {
        this.database = database
      }
    }
    class Service {
      repository: any
      constructor(repository: any) {
        this.repository = repository
      }
    }
    container.register({
      database: asClass(class DatabasePool {})
        .singleton()
        .initializer((i) => i),
      repository: asClass(Repository).singleton().initializer((i) => i),
      service: asClass(Service).singleton().initializer((i) => i),
    })
    const result = await container.initialize()
    expect(result.metrics.database.level).toBe(0)
    expect(result.metrics.repository.level).toBe(1)
    expect(result.metrics.service.level).toBe(2)
  })

  it('circular dependency is retryable', async () => {
    const container = createContainer()
    class A {
      b: any
      constructor(b: any) {
        this.b = b
      }
    }
    class B {
      a: any
      constructor(a: any) {
        this.a = a
      }
    }
    container.register({
      a: asClass(A).singleton().initializer((i) => i),
      b: asClass(B).singleton().initializer((i) => i),
    })
    let caught: any = null
    try {
      await container.initialize()
    } catch (err) {
      caught = err
    }
    expect(caught).toBeInstanceOf(AwilixResolutionError)
    // retry is allowed (no failed state)
    const retried = await container.initialize()
    expect(retried.metrics.a).toBeDefined()
  })

  it('level initializers run in parallel', async () => {
    const container = createContainer()
    const order: Array<string> = []
    container.register({
      a: asFunction(() => ({})).singleton().initializer(async (i) => {
        await new Promise((r) => setTimeout(r, 30))
        order.push('a')
        return i
      }),
      b: asFunction(() => ({})).singleton().initializer(async (i) => {
        await new Promise((r) => setTimeout(r, 5))
        order.push('b')
        return i
      }),
    })
    const started = Date.now()
    await container.initialize()
    const elapsed = Date.now() - started
    expect(order).toEqual(['b', 'a'])
    expect(elapsed).toBeLessThan(40)
  })

  it('concurrency limits parallel initializers', async () => {
    const container = createContainer()
    let active = 0
    let maxActive = 0
    container.register({
      a: asFunction(() => ({})).singleton().initializer(async (i) => {
        active++
        maxActive = Math.max(maxActive, active)
        await new Promise((r) => setTimeout(r, 20))
        active--
        return i
      }),
      b: asFunction(() => ({})).singleton().initializer(async (i) => {
        active++
        maxActive = Math.max(maxActive, active)
        await new Promise((r) => setTimeout(r, 20))
        active--
        return i
      }),
      c: asFunction(() => ({})).singleton().initializer(async (i) => {
        active++
        maxActive = Math.max(maxActive, active)
        await new Promise((r) => setTimeout(r, 20))
        active--
        return i
      }),
    })
    await container.initialize({ concurrency: 2 })
    expect(maxActive).toBeLessThanOrEqual(2)
  })

  it('returns replacement from initializer', async () => {
    const container = createContainer()
    container.register({
      service: asClass(class Service {})
        .singleton()
        .initializer(async () => ({ replaced: true })),
    })
    await container.initialize()
    expect(container.resolve('service')).toEqual({ replaced: true })
  })

  it('rollback disposes in reverse order', async () => {
    const container = createContainer()
    const disposed: Array<string> = []
    container.register({
      a: asClass(
        class A {
          dispose() {
            disposed.push('a')
          }
        },
      )
        .singleton()
        .initializer((i) => i),
      b: asClass(
        class B {
          dispose() {
            disposed.push('b')
          }
        },
      )
        .singleton()
        .initializer((i) => i),
      c: asClass(
        class C {
          dispose() {
            disposed.push('c')
          }
        },
      )
        .singleton()
        .initializer(async () => {
          throw new Error('boom')
        }),
    })
    try {
      await container.initialize()
    } catch (e) {
      /* expected */
    }
    expect(disposed.sort()).toEqual(['a', 'b'].sort())
  })

  it('rollback errors do not override original error', async () => {
    const container = createContainer()
    const original = new Error('original failure')
    container.register({
      a: asClass(
        class A {
          dispose() {
            throw new Error('dispose failure')
          }
        },
      )
        .singleton()
        .initializer((i) => i),
      b: asClass(class B {})
