#
# SPDX-License-Identifier: Apache-2.0
import ast

import testtools

from bandit.core import taint


class TaintAnalyzerTests(testtools.TestCase):
    """Unit tests for :class:`bandit.core.taint.TaintAnalyzer`."""

    @staticmethod
    def _analyze(code, aliases=None):
        tree = ast.parse(code)
        analyzer = taint.TaintAnalyzer(aliases or {})
        analyzer.analyze(tree)
        return tree, analyzer

    def _call_results(self, code, sink, index=0, aliases=None):
        """Return the taint status of ``sink``'s argument at *index*."""
        tree, analyzer = self._analyze(code, aliases)
        results = []

        class Visitor(ast.NodeVisitor):
            def visit_Call(self, node):
                qualname = analyzer._qualname(node.func)
                if qualname == sink or qualname.endswith("." + sink):
                    results.append(
                        analyzer.is_tainted(node.args[index])
                        if node.args
                        else False
                    )
                self.generic_visit(node)

        Visitor().visit(tree)
        return results

    # ------------------------------------------------------------------
    # Sources
    # ------------------------------------------------------------------

    def test_request_args_get(self):
        results = self._call_results(
            "x = request.args.get('x')\nexecute(x)", "execute"
        )
        self.assertEqual([True], results)

    def test_request_args_subscript(self):
        results = self._call_results(
            "x = request.args['x']\nexecute(x)", "execute"
        )
        self.assertEqual([True], results)

    def test_request_form_get(self):
        results = self._call_results(
            "x = request.form.get('x')\nexecute(x)", "execute"
        )
        self.assertEqual([True], results)

    def test_request_form_subscript(self):
        results = self._call_results(
            "x = request.form['x']\nexecute(x)", "execute"
        )
        self.assertEqual([True], results)

    def test_request_cookies_get(self):
        results = self._call_results(
            "x = request.cookies.get('x')\nexecute(x)", "execute"
        )
        self.assertEqual([True], results)

    def test_request_cookies_subscript(self):
        results = self._call_results(
            "x = request.cookies['x']\nexecute(x)", "execute"
        )
        self.assertEqual([True], results)

    def test_sys_argv(self):
        results = self._call_results(
            "x = sys.argv\nexecute(x)", "execute"
        )
        self.assertEqual([True], results)

    def test_sys_argv_subscript(self):
        results = self._call_results(
            "x = sys.argv[1]\nexecute(x)", "execute"
        )
        self.assertEqual([True], results)

    def test_input(self):
        results = self._call_results(
            "x = input()\nexecute(x)", "execute"
        )
        self.assertEqual([True], results)

    def test_os_environ_get(self):
        results = self._call_results(
            "x = os.environ.get('x')\nexecute(x)", "execute"
        )
        self.assertEqual([True], results)

    def test_os_environ_subscript(self):
        results = self._call_results(
            "x = os.environ['x']\nexecute(x)", "execute"
        )
        self.assertEqual([True], results)

    def test_sources_aliased(self):
        aliases = {
            "req": "flask.request",
            "operating_system": "os",
            "system": "sys",
            "inp": "builtins.input",
        }
        cases = [
            "x = req.args.get('x')\nexecute(x)",
            "x = operating_system.environ.get('x')\nexecute(x)",
            "x = system.argv[1]\nexecute(x)",
            "x = inp()\nexecute(x)",
        ]
        for code in cases:
            results = self._call_results(code, "execute", aliases=aliases)
            self.assertEqual([True], results, code)

    # ------------------------------------------------------------------
    # Propagation
    # ------------------------------------------------------------------

    def test_multihop_assignment(self):
        results = self._call_results(
            "a = request.args.get('x')\nb = a\nc = b\nexecute(c)",
            "execute",
        )
        self.assertEqual([True], results)

    def test_concatenation(self):
        results = self._call_results(
            "a = request.args.get('x')\nb = a + 'suffix'\nexecute(b)",
            "execute",
        )
        self.assertEqual([True], results)

    def test_fstring(self):
        results = self._call_results(
            "a = request.args.get('x')\nb = f'{a}'\nexecute(b)", "execute"
        )
        self.assertEqual([True], results)

    def test_percent_format(self):
        results = self._call_results(
            "a = request.args.get('x')\nb = '%s' % a\nexecute(b)", "execute"
        )
        self.assertEqual([True], results)

    def test_dot_format(self):
        results = self._call_results(
            "a = request.args.get('x')\n"
            "b = 'SELECT * FROM t WHERE id = {}'.format(a)\n"
            "execute(b)",
            "execute",
        )
        self.assertEqual([True], results)

    def test_augmented_assignment(self):
        results = self._call_results(
            "a = 'prefix'\na += request.args.get('x')\nexecute(a)",
            "execute",
        )
        self.assertEqual([True], results)

    def test_walrus(self):
        results = self._call_results(
            "if (a := request.args.get('x')):\n    execute(a)", "execute"
        )
        self.assertEqual([True], results)

    def test_call_propagation(self):
        results = self._call_results(
            "def identity(v):\n    return v\n"
            "a = request.args.get('x')\nb = identity(a)\nexecute(b)",
            "execute",
        )
        self.assertEqual([True], results)

    def test_interprocedural_param(self):
        results = self._call_results(
            "def run(cmd):\n    os.system(cmd)\n"
            "run(request.args.get('x'))",
            "system",
        )
        self.assertEqual([True], results)

    def test_nested_function_closure(self):
        results = self._call_results(
            "def outer():\n"
            "    a = request.args.get('x')\n"
            "    def inner():\n"
            "        return a\n"
            "    execute(inner())",
            "execute",
        )
        self.assertEqual([True], results)

    def test_function_returning_tainted(self):
        results = self._call_results(
            "def get():\n    return request.args.get('x')\n"
            "execute(get())",
            "execute",
        )
        self.assertEqual([True], results)

    # ------------------------------------------------------------------
    # Sanitizers / safe usage
    # ------------------------------------------------------------------

    def test_int_is_safe(self):
        results = self._call_results(
            "a = request.args.get('x')\nb = int(a)\nexecute(b)", "execute"
        )
        self.assertEqual([False], results)

    def test_shlex_quote_is_safe(self):
        results = self._call_results(
            "a = request.args.get('x')\nb = shlex.quote(a)\n"
            "os.system(b)",
            "system",
        )
        self.assertEqual([False], results)

    def test_basename_is_safe(self):
        results = self._call_results(
            "a = request.args.get('x')\nb = os.path.basename(a)\nopen(b)",
            "open",
        )
        self.assertEqual([False], results)

    def test_flask_escape_is_safe(self):
        results = self._call_results(
            "a = request.args.get('x')\nb = flask.escape(a)\n"
            "render_template_string(b)",
            "render_template_string",
        )
        self.assertEqual([False], results)

    def test_markupsafe_escape_is_safe(self):
        results = self._call_results(
            "a = request.args.get('x')\nb = markupsafe.escape(a)\n"
            "make_response(b)",
            "make_response",
        )
        self.assertEqual([False], results)

    def test_parameterized_query_is_safe(self):
        results = self._call_results(
            "a = request.args.get('x')\n"
            "execute('SELECT * FROM t WHERE id = %s', (a,))",
            "execute",
        )
        self.assertEqual([False], results)

    def test_literal_argument_is_not_tainted(self):
        results = self._call_results(
            'execute("SELECT * FROM t WHERE id = 1")', "execute"
        )
        self.assertEqual([False], results)
