	c, err := ParseConfig([]byte(`
action-pinning:
  level: semver
  allowed-owners: [global-owner]
paths:
  .github/workflows/**/*.yml:
    action-pinning:
      level: commit-sha
      allowed-actions: [foo/repo]
  .github/workflows/release.yaml:
    action-pinning:
      level: major-minor
  .github/workflows/other.yaml:
    ignore: [xxx]
`))
	if err != nil {
		t.Fatal(err)
	}

	// The global config is at the head, then matching path configs in sorted order of their globs.
	cfgs := c.actionPinningConfigsForPath(".github/workflows/release.yaml")
	if len(cfgs) != 2 {
		t.Fatalf("wanted 2 configs but got %d: %+v", len(cfgs), cfgs)
	}
	if cfgs[0].Level != "semver" {
		t.Fatalf("wanted global config first but got %+v", cfgs[0])
	}
	if cfgs[1].Level != "major-minor" {
		t.Fatalf("wanted per-path config second but got %+v", cfgs[1])
	}

	// A non-matching path only has the global config.
	cfgs2 := c.actionPinningConfigsForPath(".github/workflows/other.yaml")
	if len(cfgs2) != 1 {
		t.Fatalf("wanted 1 config but got %d: %+v", len(cfgs2), cfgs2)
	}
}
