describe('concurrency', () => {
  it('limits parallel initializers within a level', async () => {
    const active: Array<string> = []
    let maxActive = 0
    let current = 0
    const container = createContainer()
    for (let i = 0; i < 6; i++) {
      const name = `svc${i}`
      container.register({
        [name]: asFunction(() => ({}))
          .singleton()
          .initializer(async () => {
            current++
            maxActive = Math.max(maxActive, current)
            active.push(`start-${name}`)
            await new Promise((r) => setTimeout(r, 20))
            current--
            active.push(`end-${name}`)
            return {}
          }),
      })
    }
    await container.initialize({ concurrency: 2 })
    expect(maxActive).toBeLessThanOrEqual(2)
    expect(active).toHaveLength(12)
  })

  it('runs all parallel when no concurrency specified', async () => {
    let maxActive = 0
    let current = 0
    const container = createContainer()
    for (let i = 0; i < 5; i++) {
      const name = `svc${i}`
      container.register({
        [name]: asFunction(() => ({}))
          .singleton()
          .initializer(async () => {
            current++
            maxActive = Math.max(maxActive, current)
            await new Promise((r) => setTimeout(r, 10))
            current--
            return {}
          }),
      })
    }
    await container.initialize()
    expect(maxActive).toBe(5)
  })
})
