#[cfg(test)]
mod tests {
    use super::*;
    use std::cmp::Ordering;
    use std::ffi::OsString;

    fn os(s: &str) -> &OsStr {
        OsString::from(s).as_os_str()
    }

    #[test]
    fn natural_cmp_sorts_digit_runs_numerically() {
        assert_eq!(Sort::natural_cmp(os("file9"), os("file10"), true), Ordering::Less);
        assert_eq!(Sort::natural_cmp(os("file10"), os("file20"), true), Ordering::Less);
        assert_eq!(Sort::natural_cmp(os("file20"), os("file9"), true), Ordering::Greater);
        assert_eq!(Sort::natural_cmp(os("file9"), os("file9"), true), Ordering::Equal);
    }

    #[test]
    fn natural_cmp_leading_zeros_are_equal_numerically() {
        assert_eq!(Sort::natural_cmp(os("file007"), os("file7"), true), Ordering::Equal);
        assert_eq!(Sort::natural_cmp(os("file007"), os("file7"), false), Ordering::Equal);
    }

    #[test]
    fn natural_cmp_case_insensitive() {
        assert_eq!(Sort::natural_cmp(os("File9"), os("file9"), false), Ordering::Equal);
        assert_eq!(Sort::natural_cmp(os("File10"), os("file9"), false), Ordering::Greater);
        // With case-sensitive folding, "File" != "file".
        assert_eq!(Sort::natural_cmp(os("File9"), os("file9"), true), Ordering::Less);
    }

    #[test]
    fn missing_value_ordering() {
        assert_eq!(Sort::missing_value(false, true), Ordering::Less);
        assert_eq!(Sort::missing_value(false, false), Ordering::Greater);
        assert_eq!(Sort::missing_value(true, true), Ordering::Greater);
        assert_eq!(Sort::missing_value(true, false), Ordering::Less);
    }

    #[test]
    fn type_rank_orders_dir_symlink_file_other() {
        assert!(Sort::type_rank(None) > Sort::type_rank(Some(std::fs::FileType::from(0))));
    }
}
