describe('Reporter with launcher template', function() {
  const tmpDirAsync = Bluebird.promisify(tmp.dir);
  const fsReaddirAsync = Bluebird.promisify(fs.readdir);

  function mockApp(config) {
    return {
      config: config,
      on: () => {}
    };
  }

  function configFor(reportFile, extra) {
    return new (require('../../lib/config'))('ci', Object.assign({
      reporter: 'tap',
      report_file: reportFile
    }, extra || {}));
  }

  it('creates a separate file per launcher and routes results to each', function() {
    return tmpDirAsync().then(dir => {
      let reportFile = dir + '/<launcher>.xml';
      let config = configFor(reportFile);
      let app = mockApp(config);
      let stream = new PassThrough();
      let reporter = new Reporter(app, stream, reportFile);

      reporter.report('Firefox', { name: 'a', passed: true, runDuration: 1 });
      reporter.report('Chrome', { name: 'b', passed: false, runDuration: 1 });

      return reporter.close().then(function() {
        return fsReaddirAsync(dir);
      }).then(function(files) {
        expect(files.sort()).to.deep.equal(['Chrome.xml', 'Firefox.xml']);

        return Bluebird.all(files.map(f => fsReadFileAsync(dir + '/' + f, 'utf-8')));
      }).then(function(contents) {
        expect(contents.join('\n')).to.match(/Chrome: 1 tests, 0 pass, 1 fail, 0 skip/);
        expect(contents.join('\n')).to.match(/Firefox: 1 tests, 1 pass, 0 fail, 0 skip/);
      });
    });
  });

  it('stdout receives combined results', function() {
    return tmpDirAsync().then(dir => {
      let reportFile = dir + '/<launcher>.xml';
      let config = configFor(reportFile);
      let app = mockApp(config);
      let stream = new PassThrough();
      let reporter = new Reporter(app, stream, reportFile);

      reporter.report('Firefox', { name: 'a', passed: true, runDuration: 1 });
      reporter.report('Chrome', { name: 'b', passed: false, runDuration: 1 });
      reporter.finish();

      let output = stream.read().toString();
      expect(output).to.match(/tests 2/);
      expect(output).to.match(/Firefox/);
      expect(output).to.match(/Chrome/);

      return reporter.close();
    });
  });

