      return reporter.close().then(function() {
        return fsReaddirAsync(dir);
      }).then(function(files) {
        expect(files).to.deep.equal([]);
      });
    });
  });

  it('finish is idempotent', function() {
    return tmpDirAsync().then(dir => {
      let reportFile = dir + '/<launcher>.xml';
      let config = configFor(reportFile);
      let app = mockApp(config);
      let stream = new PassThrough();
