new_block = '''func evalIndexAssignment(iex *ast.IndexExpression, expr object.Object, env *object.Environment) object.Object {
	leftObj := Eval(iex.Left, env)

	if !iex.IsRange {
		// Preserve the existing single-index behavior: evaluate the index
		// before dispatching so that index evaluation errors are returned
		// even when the target type is unsupported.
		index := Eval(iex.Index, env)
		if isError(index) {
			return index
		}

		switch leftObj.Type() {
		case object.ARRAY_OBJ:
			return evalArraySingleIndexAssignment(iex, leftObj, index, expr)
		case object.HASH_OBJ:
			return evalHashIndexAssignment(iex, leftObj, index, expr)
		case object.STRING_OBJ:
			return evalStringSingleIndexAssignment(iex, leftObj, index, expr)
		}

		// Preserve the previous behavior for unsupported types: silently ignore.
		return NULL
	}

	// Range assignment.
	switch leftObj.Type() {
	case object.ARRAY_OBJ:
		return evalArrayRangeAssignment(iex, leftObj, expr, env)
	case object.STRING_OBJ:
		return evalStringRangeAssignment(iex, leftObj, expr, env)
	case object.HASH_OBJ:
		var index object.Object
		if iex.Index != nil {
			index = Eval(iex.Index, env)
			if isError(index) {
				return index
			}
		}
		return evalHashIndexAssignment(iex, leftObj, index, expr)
	}

	return NULL
}

func evalHashIndexAssignment(iex *ast.IndexExpression, leftObj object.Object, index object.Object, expr object.Object) object.Object {
	hashObject := leftObj.(*object.Hash)
	if index == nil {
		return newError(iex.Token, "unusable as hash key: NULL")
	}
	key, ok := index.(object.Hashable)
	if !ok {
		return newError(iex.Token, "unusable as hash key: %s", index.Type())
	}
	hashed := key.HashKey()
	pair := object.HashPair{Key: index, Value: expr}
	hashObject.Pairs[hashed] = pair
	return NULL
}

func evalArraySingleIndexAssignment(iex *ast.IndexExpression, leftObj object.Object, index object.Object, expr object.Object) object.Object {
	arrayObject := leftObj.(*object.Array)
	idx, ok := index.(*object.Number)
	if !ok {
		return newError(iex.Token, "index operator not supported: %s on ARRAY", index.Inspect())
	}
	idxInt := idx.Int()
	elems := arrayObject.Elements
	if idxInt < 0 {
		return newError(iex.Token, "index out of range: %d", idxInt)
	}
	if idxInt >= len(elems) {
		// expand the array by appending Null objects
		for i := len(elems); i <= idxInt; i++ {
			elems = append(elems, NULL)
		}
		arrayObject.Elements = elems
	}
	elems[idxInt] = expr
	return NULL
}

func evalArrayRangeAssignment(iex *ast.IndexExpression, leftObj object.Object, expr object.Object, env *object.Environment) object.Object {
	arrayObject := leftObj.(*object.Array)

	// Range assignment (two-part or three-part slice).
	indices, errObj := evalRangeIndices(iex, len(arrayObject.Elements), env, "ARRAY")
	if errObj != nil {
		return errObj
	}

	if arr, ok := expr.(*object.Array); ok {
		if len(arr.Elements) != len(indices) {
			return newError(iex.Token, "range assignment size mismatch: target=%d value=%d", len(indices), len(arr.Elements))
		}
		for i, idx := range indices {
			arrayObject.Elements[idx] = arr.Elements[i]
		}
	} else {
		// Broadcast the value across all selected target indexes.
		for _, idx := range indices {
			arrayObject.Elements[idx] = expr
		}
	}
	return NULL
}

func evalStringSingleIndexAssignment(iex *ast.IndexExpression, leftObj object.Object, index object.Object, expr object.Object) object.Object {
	stringObject := leftObj.(*object.String)
	runes := []rune(stringObject.Value)

	str, ok := expr.(*object.String)
	if !ok {
		return newError(iex.Token, "index assignment expects single-character STRING value, got %s", expr.Type())
	}
	valueRunes := []rune(str.Value)
	if len(valueRunes) != 1 {
		return newError(iex.Token, "index assignment expects single-character STRING value, got %d characters", len(valueRunes))
	}

	num, ok := index.(*object.Number)
	if !ok {
		return newError(iex.Token, "index operator not supported: %s on STRING", index.Inspect())
	}
	idx := num.Int()
	if idx < 0 {
		idx = len(runes) + idx
		if idx < 0 {
			return newError(iex.Token, "index out of range: %d", num.Int())
		}
	}
	if idx >= len(runes) {
		return newError(iex.Token, "index out of range: %d", num.Int())
	}
	runes[idx] = valueRunes[0]
	stringObject.Value = string(runes)
	return NULL
}

func evalStringRangeAssignment(iex *ast.IndexExpression, leftObj object.Object, expr object.Object, env *object.Environment) object.Object {
	stringObject := leftObj.(*object.String)
	runes := []rune(stringObject.Value)

	// Range assignment (two-part or three-part slice).
	indices, errObj := evalRangeIndices(iex, len(runes), env, "STRING")
	if errObj != nil {
		return errObj
	}

	str, ok := expr.(*object.String)
	if !ok {
		return newError(iex.Token, "range assignment expects STRING value, got %s", expr.Type())
	}
	valueRunes := []rune(str.Value)

	if len(indices) == 0 {
		// Zero-length targets: any non-empty replacement is a size mismatch.
		if len(valueRunes) > 0 {
			return newError(iex.Token, "range assignment size mismatch: target=%d value=%d", 0, len(valueRunes))
		}
		return NULL
	}

	if len(valueRunes) == 1 {
		// A single character is broadcast across all selected target indexes.
		for _, idx := range indices {
			runes[idx] = valueRunes[0]
		}
	} else if len(valueRunes) == len(indices) {
		for i, idx := range indices {
			runes[idx] = valueRunes[i]
		}
	} else {
		return newError(iex.Token, "range assignment size mismatch: target=%d value=%d", len(indices), len(valueRunes))
	}
	stringObject.Value = string(runes)
	return NULL
}

