// maybeAppendIndex applies the module directory convention: if a candidate
// path does not end in .abs, treat it as a directory and look for index.abs.
func maybeAppendIndex(path string) string {
	if filepath.Ext(path) != ".abs" {
		return filepath.Join(path, "index.abs")
	}
	return path
}

// resolveModuleFile resolves a require target to its canonical module path.
// Stdlib targets (prefixed with '@') are returned in their canonical key
// form. An empty string is returned when the module cannot be found in any
// candidate directory.
func resolveModuleFile(env *object.Environment, target string) string {
	if strings.HasPrefix(target, "@") {
		return maybeAppendIndex(target)
	}

	target = unaliasModulePath(target)

	if filepath.IsAbs(target) {
		candidate := maybeAppendIndex(target)
		if fileExists(candidate) {
			return canonicalModulePath(candidate)
		}
		return ""
	}

	for _, dir := range moduleSearchDirs(env) {
		candidate := maybeAppendIndex(filepath.Join(dir, target))
		if fileExists(candidate) {
			return canonicalModulePath(candidate)
		}
	}
	return ""
}
