import { createContainer } from '../container'
import { asClass, asFunction, asValue } from '../resolvers'
import {
  AwilixInitializationError,
  AwilixNotInitializedError,
  AwilixResolutionError,
} from '../errors'

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms))

describe('container.initialize', () => {
  it('initializes registrations and reports metrics', async () => {
    const events: Array<string> = []
    const container = createContainer()
    container.register({
      config: asValue({ url: 'x' }),
    })
    container.register({
      database: asClass(
        class DatabasePool {
          connect() {}
        },
      )
        .singleton()
        .initializer(async (instance: any) => {
          events.push('db-start')
          await sleep(20)
          events.push('db-end')
          return instance
        }),
    })
    container.register({
      service: asClass(
        class Service {
          constructor(deps: any) {
            deps.database
            deps.config
          }
        },
      )
        .singleton()
        .initializer(async (instance: any) => {
          events.push('svc-start')
          await sleep(10)
          events.push('svc-end')
          return instance
        }),
    })

    const result = await container.initialize({ concurrency: 5 })
    expect(result.totalDuration).toBeGreaterThanOrEqual(0)
    expect(result.metrics.database).toBeDefined()
    expect(result.metrics.database.duration).toBeGreaterThanOrEqual(0)
    expect(container.cradle.database).toBeTruthy()
    expect(events).toEqual([
      'db-start',
      'db-end',
      'svc-start',
      'svc-end',
    ])
  })

  it('orders dependencies into levels', async () => {
    const events: Array<string> = []
    const container = createContainer({
      injectionMode: 'CLASSIC',
    } as any)
    container.register({
      config: asValue({ url: 'x' }),
    })
    container.register({
      database: asClass(
        class DatabasePool {
          constructor(config: any) {
            void config
          }
        },
      )
        .singleton()
        .initializer(async (instance: any) => {
          events.push('db')
          await sleep(20)
          return instance
        }),
    })
    container.register({
      service: asClass(
        class Service {
          database: any
          constructor(database: any) {
            this.database = database
          }
        },
      )
        .singleton()
        .initializer(async (instance: any) => {
          events.push('service')
          await sleep(5)
          return instance
        }),
    })

    const result = await container.initialize({ concurrency: 5 })
    expect(result.metrics.database.level).toBe(0)
    expect(result.metrics.service.level).toBe(1)
    expect(events).toEqual(['db', 'service'])
  })

  it('rolls back on failure in reverse order', async () => {
    const events: Array<string> = []
    const container = createContainer()
    container.register({
      a: asFunction(() => ({ name: 'a' }))
        .singleton()
        .initializer(async (i: any) => {
          events.push('a-init')
          return i
        })
        .disposer(async () => {
          events.push('a-dispose')
        }),
    })
    container.register({
      b: asFunction(() => ({ name: 'b' }))
        .singleton()
        .initializer(async () => {
          events.push('b-init')
          throw new Error('boom')
        })
        .disposer(async () => {
          events.push('b-dispose')
        }),
    })

    try {
      await container.initialize({ concurrency: 5 })
      throw new Error('should have thrown')
    } catch (err: any) {
      expect(err).toBeInstanceOf(AwilixInitializationError)
      expect(err.message).toContain('b')
      expect(err.message).toContain('boom')
      expect(err.cause).toBeInstanceOf(Error)
      expect(err.cause.message).toBe('boom')
    }
    expect(events).toEqual(['a-init', 'b-init', 'a-dispose'])
  })

  it('allows in-flight initializers to complete before rollback', async () => {
    const events: Array<string> = []
    const container = createContainer()
    container.register({
      slow: asFunction(() => ({ name: 'slow' }))
        .singleton()
        .initializer(async (i: any) => {
          events.push('slow-start')
          await sleep(40)
          events.push('slow-end')
          return i
        })
        .disposer(async () => {
          events.push('slow-dispose')
        }),
    })
    container.register({
      fail: asFunction(() => ({ name: 'fail' }))
        .singleton()
        .initializer(async () => {
          events.push('fail')
          throw new Error('nope')
        }),
    })

    try {
      await container.initialize({ concurrency: 2 })
      throw new Error('should throw')
    } catch (e) {
      // expected
    }
    expect(events).toContain('slow-end')
    expect(events.indexOf('slow-end')).toBeLessThan(
      events.indexOf('slow-dispose'),
    )
  })

  it('does not let disposer errors override the original error', async () => {
    const container = createContainer()
    container.register({
      a: asFunction(() => ({}))
        .singleton()
        .initializer(async (i: any) => i)
        .disposer(async () => {
          throw new Error('dispose-error')
        }),
    })
    container.register({
      b: asFunction(() => ({}))
        .singleton()
        .initializer(async () => {
          throw new Error('init-error')
        }),
    })
    try {
      await container.initialize()
      throw new Error('should throw')
    } catch (err: any) {
      expect(err.message).toContain('init-error')
      expect(err.cause.message).toBe('init-error')
    }
  })

  it('is idempotent after success', async () => {
    let count = 0
    const container = createContainer()
    container.register({
      svc: asFunction(() => ({}))
        .singleton()
        .initializer(async (i: any) => {
          count++
          return i
        }),
    })
    const r1 = await container.initialize()
    const r2 = await container.initialize()
    expect(count).toBe(1)
    expect(r2).toEqual(r1)
  })

  it('throws a re-initialization error after failure', async () => {
    const container = createContainer()
    container.register({
      b: asFunction(() => ({}))
        .singleton()
        .initializer(async () => {
          throw new Error('x')
        }),
    })
    try {
      await container.initialize()
    } catch (e) {
      // expected
    }
    try {
      await container.initialize()
      throw new Error('should throw')
    } catch (err: any) {
      expect(err.message).toMatch(/previously failed|Cannot re-initialize/)
    }
  })

  it('throws AwilixNotInitializedError when resolving an uninitialized service', async () => {
    const container = createContainer()
    container.register({
      db: asFunction(() => ({}))
        .singleton()
        .initializer(async (i: any) => i),
    })
    container.register({
      plain: asValue(42),
    })
    expect(container.resolve('plain' as any)).toBe(42)
    try {
      container.resolve('db' as any)
      throw new Error('should throw')
    } catch (err: any) {
      expect(err).toBeInstanceOf(AwilixNotInitializedError)
      expect(err.message).toContain('not initialized')
    }
  })

  it('uses a replacement returned by the initializer', async () => {
    const container = createContainer()
    container.register({
      db: asFunction(() => ({ original: true }))
        .singleton()
        .initializer(() => ({ original: false, replaced: true })),
    })
    await container.initialize()
    const db: any = container.resolve('db' as any)
    expect(db.replaced).toBe(true)
    expect(db.original).toBe(false)
  })

  it('initializes scoped containers independently', async () => {
    let parentInits = 0
    const container = createContainer()
    container.register({
      db: asFunction(() => ({}))
        .singleton()
        .initializer(async (i: any) => {
          parentInits++
          return i
        }),
    })
    await container.initialize()
    const scope = container.createScope()
    scope.register({
      local: asFunction(() => ({}))
        .scoped()
        .initializer(async (i: any) => i),
    })
    const result = await scope.initialize()
    expect(parentInits).toBe(1)
    expect(result.metrics.local.level).toBe(0)
    expect(scope.resolve('db' as any)).toBeTruthy()
    expect(parentInits).toBe(1)
  })

  it('throws AwilixResolutionError on circular dependencies and allows retry', async () => {
    const container = createContainer({
      injectionMode: 'CLASSIC',
    } as any)
    container.register({
      a: asFunction((b: any) => ({ b }))
        .singleton()
        .initializer(async (i: any) => i),
    })
    container.register({
      b: asFunction((a: any) => ({ a }))
        .singleton()
        .initializer(async (i: any) => i),
    })
    try {
      await container.initialize()
      throw new Error('should throw')
    } catch (err: any) {
      expect(err).toBeInstanceOf(AwilixResolutionError)
    }
    try {
      await container.initialize()
      throw new Error('should throw')
    } catch (err: any) {
      expect(err).toBeInstanceOf(AwilixResolutionError)
    }
  })

  it('limits parallel initializers within a level', async () => {
    let maxActive = 0
    let current = 0
    const container = createContainer()
    for (let i = 0; i < 6; i++) {
      const name = `svc${i}`
      container.register({
        [name]: asFunction(() => ({}))
          .singleton()
          .initializer(async () => {
            current++
            maxActive = Math.max(maxActive, current)
            await new Promise((r) => setTimeout(r, 20))
            current--
            return {}
          }),
      })
    }
    await container.initialize({ concurrency: 2 })
    expect(maxActive).toBeLessThanOrEqual(2)
  })

  it('runs all initializers in parallel without a concurrency limit', async () => {
    let maxActive = 0
    let current = 0
    const container = createContainer()
    for (let i = 0; i < 5; i++) {
      const name = `svc${i}`
      container.register({
        [name]: asFunction(() => ({}))
          .singleton()
          .initializer(async () => {
            current++
            maxActive = Math.max(maxActive, current)
            await new Promise((r) => setTimeout(r, 10))
            current--
            return {}
          }),
      })
    }
    await container.initialize()
    expect(maxActive).toBe(5)
  })

  it('works with initializer passed via resolver options', async () => {
    const container = createContainer()
    container.register({
      db: asFunction(
        () => ({ original: true }),
        {
          lifetime: 'SINGLETON',
          initializer: async () => ({ replaced: true }),
        },
      ),
    })
    await container.initialize()
    const db: any = container.resolve('db' as any)
    expect(db.replaced).toBe(true)
  })
})
