		const options = vi.fn(async (search: string) => [{ value: `new-${search}` }]);
		const instance = new AutocompletePrompt({
			input,
			output,
			render: () => 'foo',
			options,
			debounceMs: 10,
			cacheResults: true,
			staleWhileRevalidate: true,
		});

		instance.prompt();
		await flushPromises();
		expect(instance.filteredOptions).toEqual([{ value: 'new-' }]);

		// Fetch 'a', store cache
		input.emit('keypress', 'a', { name: 'a' });
		await vi.advanceTimersByTimeAsync(10);
		await flushPromises();
		expect(options.mock.calls.length).toBe(2);
		expect(instance.filteredOptions).toEqual([{ value: 'new-a' }]);

		// Clear input, retype 'a' -> cache hit, serve cached, background refetch
		input.emit('keypress', '', { name: 'backspace' });
		await vi.advanceTimersByTimeAsync(10);
		await flushPromises();

		input.emit('keypress', 'a', { name: 'a' });
		// loading should be true synchronously because background refetch started
		expect(instance.loading).toBe(true);
		expect(instance.filteredOptions).toEqual([{ value: 'new-a' }]);
		expect(options.mock.calls.length).toBe(3);

		await vi.advanceTimersByTimeAsync(10);
		await flushPromises();
		expect(instance.loading).toBe(false);
		expect(instance.filteredOptions).toEqual([{ value: 'new-a' }]);
	});

	test('minSearchLength suppresses fetching and sets searchTooShort; empty fetches', async () => {
		const options = vi.fn(async () => [{ value: 'x' }]);
		const instance = new AutocompletePrompt({
			input,
