		// Type 'p' -> 'ap' (long enough)
		input.emit('keypress', 'p', { name: 'p' });
		await vi.advanceTimersByTimeAsync(10);
		await flushPromises();
		expect(instance.searchTooShort).toBe(false);
		expect(options.mock.calls.length).toBe(2);
	});

	test('maxRetries keeps loading and retries, then fallbackOptions shown', async () => {
		const options = vi.fn(async () => {
			throw new Error('network');
		});
		const instance = new AutocompletePrompt({
			input,
			output,
			render: () => 'foo',
			options,
			debounceMs: 0,
			maxRetries: 2,
			retryDelay: 10,
			retryBackoff: 'linear',
			fallbackOptions: [{ value: 'fallback' }],
		});

		instance.prompt();
		await flushPromises();
		expect(instance.retryCount).toBe(1);
		expect(instance.loading).toBe(true);

		await vi.advanceTimersByTimeAsync(10);
		await flushPromises();
		expect(instance.retryCount).toBe(2);
		expect(instance.loading).toBe(true);

		await vi.advanceTimersByTimeAsync(10);
		await flushPromises();
		expect(instance.retryCount).toBe(2);
		expect(instance.loading).toBe(false);
		expect(instance.loadError).toBe('network');
		expect(instance.filteredOptions).toEqual([{ value: 'fallback' }]);
	});

	test('exponential retry backoff doubles delay', async () => {
		const options = vi.fn(async () => {
			throw new Error('network');
		});
		const instance = new AutocompletePrompt({
			input,
			output,
			render: () => 'foo',
			options,
			debounceMs: 0,
			maxRetries: 2,
			retryDelay: 10,
			retryBackoff: 'exponential',
		});

		instance.prompt();
		await flushPromises();
		expect(instance.retryCount).toBe(1);

		// first retry after 10ms
		await vi.advanceTimersByTimeAsync(10);
		await flushPromises();
		expect(instance.retryCount).toBe(2);

		// second retry after 20ms (doubled)
		await vi.advanceTimersByTimeAsync(15);
		expect(instance.retryCount).toBe(2);
		await vi.advanceTimersByTimeAsync(5);
		await flushPromises();
		expect(instance.loading).toBe(false);
		expect(instance.loadError).toBe('network');
	});

	test('loadingMinDuration keeps loading true and defers application', async () => {
		let resolveFetch!: (v: { value: string }[]) => void;
		const fetchPromise = new Promise<{ value: string }[]>((res) => {
			resolveFetch = res;
		});
		const instance = new AutocompletePrompt({
			input,
			output,
			render: () => 'foo',
			options: async () => fetchPromise,
			debounceMs: 0,
			loadingMinDuration: 50,
		});

		instance.prompt();
		expect(instance.loading).toBe(true);

		resolveFetch([{ value: 'apple' }]);
		await fetchPromise;
		await flushPromises();
		expect(instance.loading).toBe(true); // still loading due to min duration

		await vi.advanceTimersByTimeAsync(50);
		expect(instance.loading).toBe(false);
		expect(instance.filteredOptions).toEqual([{ value: 'apple' }]);
	});

	test('close resets async state and aborts', async () => {
		const options = vi.fn(async () => {
			return new Promise<{ value: string }[]>(() => {});
		});
		const instance = new AutocompletePrompt({
			input,
			output,
			render: () => 'foo',
			options,
			debounceMs: 0,
		});

		const promise = instance.prompt();
		expect(instance.loading).toBe(true);

		input.emit('keypress', '\x03', { name: 'c', ctrl: true });
		await promise;
		await flushPromises();
		expect(instance.loading).toBe(false);
		expect(instance.loadError).toBe('');
		expect(instance.searchTooShort).toBe(false);
		expect(instance.retryCount).toBe(0);
	});
});
