describe('container.initialize edge cases', () => {
  it('orders by transitive dependencies through non-initializer services', async () => {
    const container = createContainer()
    const order: Array<string> = []

    // db has an initializer, middle does not, top depends on middle
    // which depends on db. top must still wait for db.
    container.register({
      db: asFunction(() => ({})).singleton().initializer(async (instance) => {
        order.push('db')
        await delay(5)
        return instance
      }),
      middle: asFunction(({ db }: any) => ({ db })),
      top: asFunction(({ middle }: any) => ({ middle })).initializer(
        async (instance) => {
          order.push('top')
          return instance
        },
      ),
    })

    const result = await container.initialize()

    expect(order).toEqual(['db', 'top'])
    expect(result.metrics.db.level).toBe(0)
    expect(result.metrics.top.level).toBe(1)
  })

  it('resolves an initialized parent singleton from a scoped container', async () => {
    const parent = createContainer()
    parent.register({
      db: asFunction(() => ({ state: 'initial' }))
        .singleton()
        .initializer(async (instance) => ({ ...instance, state: 'ready' })),
    })

    await parent.initialize()

    const child = parent.createScope()
    child.register({
      svc: asFunction(({ db }: any) => ({ db })).initializer(
        async (instance) => instance,
      ),
    })

    const result = await child.initialize()

    expect(result.metrics.svc.level).toBe(0)
    expect(child.resolve('svc').db.state).toBe('ready')
  })
})
